def main():
    if not os.path.isdir('lib'):
        print('❌ 프로젝트 폴더(C:\\apps\\mp3_player_new)에서 실행해 주세요.')
        sys.exit(1)
    texts, crlf = {}, {}
    for f, _, _, _ in EDITS:
        if f in texts: continue
        if not os.path.exists(f):
            print(f'❌ {f} 파일이 없어요.'); sys.exit(1)
        raw = open(f, 'rb').read().decode('utf-8')
        crlf[f] = '\r\n' in raw
        texts[f] = raw.replace('\r\n', '\n')
    # 이미 했는지: 지울 것 중 하나도 안 남아 있으면
    if all(texts[f].count(old) == 0 for f, _, old, _ in EDITS):
        print('이미 적용돼 있어요'); return
    ok = True; lines = 0
    for f, name, old, new in EDITS:
        n = texts[f].count(old)
        if n == 1:
            texts[f] = texts[f].replace(old, new)
            k = old.count('\n'); lines += k
            print(f'✔ {os.path.basename(f)} - {name} ({k}줄)')
        else:
            print(f'❌ {os.path.basename(f)} - {name} (찾을 코드가 {n}군데)')
            ok = False
    if not ok:
        print('\n❌ 못 찾은 곳이 있어서 아무것도 저장하지 않았어요.'); sys.exit(1)
    for f in texts:
        t = texts[f].replace('\n', '\r\n') if crlf[f] else texts[f]
        open(f, 'wb').write(t.encode('utf-8'))
    print(f'\n완료! 파일 {len(texts)}개에서 {len(EDITS)}곳, 약 {lines}줄 지웠어요.')

if __name__ == '__main__':
    main()
